const input = $input.first().json;
// Recover ticket fields from a normal webhook body or legacy nested webhook bodies.
const allowed = ['ticketId','title','description','category','priority','assignedTeam','status','createdAt','aiReason','aiSuggestion','suggestedResponse','deduplication','alert','sla','actor'];
const layers = [];
let value = input;
for (let depth = 0; depth < 16; depth++) {
  if (typeof value === 'string') value = JSON.parse(value);
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Ticket payload must be a JSON object');
  layers.push(value);
  if (!Object.prototype.hasOwnProperty.call(value, 'body')) break;
  value = value.body;
  if (depth === 15) throw new Error('Webhook body nesting is too deep');
}
const ticket = {};
const trace = [];
for (const layer of layers.reverse()) {
  for (const key of allowed) if (Object.prototype.hasOwnProperty.call(layer, key)) ticket[key] = layer[key];
  if (Array.isArray(layer.workflowTrace)) for (const entry of layer.workflowTrace) {
    if (typeof entry === 'string' && entry.length <= 80 && !trace.includes(entry)) trace.push(entry);
  }
}
ticket.workflowTrace = trace.slice(-32);
return [{ json: ticket }];

const input = $input.first().json;
const ticket = { ...input };
if (typeof ticket.ticketId !== 'string' || !ticket.ticketId.trim() || ticket.ticketId.length > 100) throw new Error('ticketId is required and must be at most 100 characters');
ticket.ticketId = ticket.ticketId.trim();
for (const key of ['title','description','category','priority','status','assignedTeam','aiReason','aiSuggestion','suggestedResponse']) {
  if (ticket[key] !== undefined && typeof ticket[key] !== 'string') throw new Error(key + ' must be a string');
}
if (ticket.title && ticket.title.length > 200) throw new Error('title is too long');
if (ticket.description && ticket.description.length > 10000) throw new Error('description is too long');
return [{ json: ticket }];

const input = $input.first().json;
const source = input.actor;
const actor = { type: 'system' };
if (source && typeof source === 'object' && !Array.isArray(source)) {
  for (const key of ['id','name']) if (typeof source[key] === 'string') actor[key] = source[key].slice(0,200);
  if (actor.id) actor.type = 'user';
}
return [{ json: { ...input, actor } }];

const input = $input.first().json;
const snapshot = { ticketId: input.ticketId };
for (const key of ['title','category','priority','status','assignedTeam','createdAt']) if (input[key] !== undefined) snapshot[key] = input[key];
return [{ json: { ...input, _auditSnapshot: snapshot } }];

const input = $input.first().json;
const source = input.alert;
const summary = { present: Boolean(source && typeof source === 'object') };
if (summary.present) {
  summary.required = source.required === true;
  summary.sent = source.sent === true;
  summary.status = typeof source.status === 'string' ? source.status : 'unknown';
}
return [{ json: { ...input, _auditAlert: summary } }];

const input = $input.first().json;
const source = input.sla;
const summary = { present: Boolean(source && typeof source === 'object') };
if (summary.present) {
  summary.breached = source.breached === true;
  summary.escalationSent = source.escalationSent === true;
  if (Number.isFinite(source.targetHours)) summary.targetHours = source.targetHours;
  if (typeof source.dueAt === 'string' && Number.isFinite(new Date(source.dueAt).getTime())) summary.dueAt = new Date(source.dueAt).toISOString();
  if (typeof source.state === 'string') summary.state = source.state;
}
return [{ json: { ...input, _auditSla: summary } }];

const input = $input.first().json;
const workflowTrace = [...(input.workflowTrace ?? [])];
if (!workflowTrace.includes('WF09')) workflowTrace.push('WF09');
return [{ json: { ...input, workflowTrace } }];

const input = $input.first().json;
const processedAt = new Date().toISOString();
const auditLog = {
  event: 'ticket.processed',
  eventId: 'ticket.processed:' + input.ticketId + ':' + String($execution.id),
  ticketId: input.ticketId,
  processedAt,
  actor: input.actor,
  ticket: input._auditSnapshot,
  alert: input._auditAlert,
  sla: input._auditSla,
  workflowTrace: [...input.workflowTrace],
  persisted: false,
  storageStatus: 'not_configured'
};
return [{ json: { ...input, auditLog } }];

const input = $input.first().json;
const event = input.auditLog;
if (!event || event.event !== 'ticket.processed' || event.ticketId !== input.ticketId || !event.eventId) throw new Error('Invalid audit event identity');
if (!Number.isFinite(new Date(event.processedAt).getTime())) throw new Error('Invalid audit timestamp');
if (!event.workflowTrace.includes('WF09') || event.persisted !== false) throw new Error('Invalid audit completion metadata');
return [{ json: input }];

const input = $input.first().json;
const { _auditSnapshot, _auditAlert, _auditSla, ...ticket } = input;
return [{ json: { ...ticket, processingComplete: true } }];
